    where s.source_url = 'https://www.imi.gov.my/index.php/en/main-services/pass/visitor-pass/social-visit-pass/long-term-social-visit-pass/'
      and v.is_active
      and (s.visa_type_id is null
           or s.visa_type_id = (select id from public.visa_types
                                 where visaai_id = 'my-long-term-social-visit-pass'))
    order by s.visa_type_id nulls last
    limit 1),
  'approval to work or conduct business will be endorsed in the applicant’s passport.', 'manual', 1.00,
  'draft', 80, '2026-08-24'::timestamptz
)
